import { Component } from '@angular/core';
import { UserService } from '../user.service';
import { ActivatedRoute, Router } from '@angular/router';
import { NgForm } from '@angular/forms';
import { EMAIL_DOMAINS } from 'src/app/constants';

@Component({
    selector: 'app-login',
    templateUrl: './login.component.html',
    styleUrls: ['./login.component.css']
})
export class LoginComponent {

    emailDomains = EMAIL_DOMAINS;

    constructor(private userService: UserService, private router: Router, private route: ActivatedRoute) { }

    login(form: NgForm) {
        if (form.invalid) {
            return;
        }
        this.userService.login(form.value.email, form.value.password).subscribe({
            next: () => {
                const returnUrl = this.route.snapshot.queryParamMap.get('returnUrl');
                if (returnUrl) {
                    this.router.navigateByUrl(returnUrl);
                } else {
                    this.router.navigate(['/themes']);
                }
            },
            error: (err) => {
                console.error(err);
            }
        });
    }
}
<div class="container">
    <form
        class="login"
        #form="ngForm"
        (ngSubmit)="login(form)"
    >

        <fieldset>
            <h2>Login Form</h2>
            <p class="field field-icon">
                <label for="email"><span><i class="fas fa-envelope"></i></span></label>
                <input
                    class="input-error"
                    type="email"
                    name="email"
                    id="email"
                    placeholder="john.doe@gmail.com"
                    ngModel
                    #inputEmail="ngModel"
                    required
                    [appEmail]="emailDomains"
                >
            </p>

            <ng-container *ngIf="inputEmail.touched">
                <p
                    class="error"
                    *ngIf="inputEmail.errors?.['required']"
                >Email is required!</p>
                <p
                    class="error"
                    *ngIf="inputEmail.errors?.['emailValidator']"
                >Email is not valid!</p>
            </ng-container>


            <p class="field field-icon">
                <label for="password"><span><i class="fas fa-lock"></i></span></label>
                <input
                    type="password"
                    name="password"
                    id="password"
                    placeholder="******"
                    ngModel
                    #inputPassword="ngModel"
                    required
                    minlength="5"
                >
            </p>
            <ng-container *ngIf="inputPassword.touched">
                <p
                    class="error"
                    *ngIf="inputPassword.errors?.['required']"
                > Password is required! </p>
                <p
                    class="error"
                    *ngIf="inputPassword.errors?.['minlength']"
                > Password must be at least 5 characters!
                </p>
            </ng-container>

            <button>Login</button>

            <p class="text-center">
                Have an account?
                <a routerLink="/auth/register">Register</a>
            </p>

        </fieldset>
    </form>
</div>
